#pragma once

#include "Core/JamBalance.h"
#include "Core/JamTypes.h"
#include "CoreMinimal.h"

/**
 * The Publisher's cuts. His health stops at each threshold; there he grabs two of the hero's mechanics and the player
 * gives one of them away on a card. While the card is up the fight stands still: nothing flies, nothing hurts, only the
 * card's clock runs. The last threshold is not a choice: he takes whatever is left.
 * Tests: Jam.Steal.*
 */
namespace JamStealRules
{
inline constexpr int32 ThresholdCount = 4;

/** Boss health at which the steal number Index waits; 0 when there is no such steal. */
JAMGAME_API float ThresholdHealth(int32 Index, const FJamBalanceData& Balance);

/** Health after a hit that may not cross the floor. */
JAMGAME_API float ClampToThreshold(float Health, float Floor);

/** What goes on the card: two of the hero's mechanics picked by the stream, or all of them with bTakesAll. */
JAMGAME_API TArray<EJamMechanic> Offer(const FJamLedger& Ledger, bool bTakesAll, FRandomStream& Stream);

/** The grab: clears the stage and puts the card up. A hero with nothing left is passed by without a card. */
JAMGAME_API void Open(FJamFight& Fight, const FJamBalanceData& Balance);

/** One step of the open card. An answer counts once the card is unlocked; when its time is up the left option goes. */
JAMGAME_API void Advance(FJamFight& Fight, int32 Choice, const FJamBalanceData& Balance);

/** Settles the steal: the picked option (or everything) goes to the boss and the fight goes on. */
JAMGAME_API void Resolve(FJamFight& Fight, int32 Choice, const FJamBalanceData& Balance);

/** The card's timer for the screen: 1 when it opens, 0 when the time is up. */
JAMGAME_API float TimeLeft(const FJamStealState& Steal, float Tick);
} // namespace JamStealRules
#include "Sim/JamStealRules.h"

#include "Sim/JamFightOps.h"
#include "Sim/JamLoadoutRules.h"

namespace
{
// Options of a card that is a choice.
constexpr int32 OptionsOnACard = 2;
} // namespace

float JamStealRules::ThresholdHealth(int32 Index, const FJamBalanceData& Balance)
{
	const float Shares[ThresholdCount] = { Balance.StealThreshold1, Balance.StealThreshold2, Balance.StealThreshold3,
		Balance.StealThreshold4 };
	return Index >= 0 && Index < ThresholdCount ? Shares[Index] * Balance.BossHealth : 0.f;
}

float JamStealRules::ClampToThreshold(float Health, float Floor)
{
	return FMath::Max(Health, Floor);
}

TArray<EJamMechanic> JamStealRules::Offer(const FJamLedger& Ledger, bool bTakesAll, FRandomStream& Stream)
{
	TArray<EJamMechanic> Result = JamLoadoutRules::Owned(Ledger, EJamSide::Hero);
	if (bTakesAll)
	{
		return Result;
	}
	for (int32 Index = Result.Num() - 1; Index > 0; --Index)
	{
		Result.Swap(Index, Stream.RandRange(0, Index));
	}
	Result.SetNum(FMath::Min(Result.Num(), OptionsOnACard));
	return Result;
}

void JamStealRules::Open(FJamFight& Fight, const FJamBalanceData& Balance)
{
	FJamStealState& Steal = Fight.Steal;
	Steal.bTakesAll = Steal.Done >= ThresholdCount - 1;
	Steal.Offer = Offer(Fight.Ledger, Steal.bTakesAll, Fight.Stream);
	if (Steal.Offer.IsEmpty())
	{
		++Steal.Done;
		Steal.Floor = ThresholdHealth(Steal.Done, Balance);
		return;
	}
	JamFightOps::ClearStage(Fight);
	Steal.StartTick = Fight.Tick;
	Steal.OpenTick = Fight.Tick + JamSim::Ticks(Balance.StealChoiceLock);
	Steal.EndTick = Fight.Tick + JamSim::Ticks(Balance.StealChoiceSeconds);
	Fight.Phase = EJamPhase::Steal;
	const FVector2D BossPos = Fight.Fighters[EJamSide::Boss].Pos;
	JamFightOps::AddEvent(Fight, EJamEvent::StealOpened, EJamSide::Boss, 0, BossPos, static_cast<float>(Steal.Offer.Num()));
}

void JamStealRules::Advance(FJamFight& Fight, int32 Choice, const FJamBalanceData& Balance)
{
	const FJamStealState& Steal = Fight.Steal;
	if (Fight.Tick >= Steal.EndTick)
	{
		Resolve(Fight, 0, Balance);
	}
	else if (Fight.Tick >= Steal.OpenTick && Steal.Offer.IsValidIndex(Choice))
	{
		Resolve(Fight, Choice, Balance);
	}
}

void JamStealRules::Resolve(FJamFight& Fight, int32 Choice, const FJamBalanceData& Balance)
{
	FJamStealState& Steal = Fight.Steal;
	const int32 Picked = Steal.Offer.IsValidIndex(Choice) ? Choice : 0;
	const FVector2D BossPos = Fight.Fighters[EJamSide::Boss].Pos;
	for (int32 Index = 0; Index < Steal.Offer.Num(); ++Index)
	{
		if (Steal.bTakesAll || Index == Picked)
		{
			const EJamMechanic Mechanic = Steal.Offer[Index];
			JamLoadoutRules::Give(Fight.Ledger, Mechanic, EJamSide::Boss);
			JamFightOps::AddEvent(Fight, EJamEvent::StealResolved, EJamSide::Boss, 0, BossPos, static_cast<float>(Mechanic));
		}
	}
	Steal.Offer.Reset();
	Steal.bTakesAll = false;
	++Steal.Done;
	Steal.Floor = ThresholdHealth(Steal.Done, Balance);
	Fight.Phase = EJamPhase::Fight;
	// He looks at what he got before he uses it: the player gets a breath after the card.
	Fight.Boss.BusyUntilTick = Fight.Tick + JamSim::Ticks(Balance.BossRecovery);
}

float JamStealRules::TimeLeft(const FJamStealState& Steal, float Tick)
{
	const float Whole = static_cast<float>(FMath::Max(1, Steal.EndTick - Steal.StartTick));
	return FMath::Clamp((Steal.EndTick - Tick) / Whole, 0.f, 1.f);
}
#pragma once

#include "Core/JamBalance.h"
#include "Core/JamTypes.h"
#include "CoreMinimal.h"
#include "Misc/Optional.h"

/**
 * The Publisher's slam grows with each cut (T-050): one circle on the hero before the first cut, then a pattern that
 * also closes the floor around him and the hero's ways out. The circles land one after another, from him outwards.
 * There is always a spot the hero can walk to in time, and a cash stack on the floor is never covered.
 * Tests: Jam.Slam.*
 */
namespace JamSlamRules
{
/** How many circles one slam puts down after CutsDone cuts. */
JAMGAME_API int32 CircleCount(int32 CutsDone, const FJamBalanceData& Balance);

/**
 * The circles of one slam put down on Tick, in landing order: the one around the boss, the one on the hero, then the
 * cutters behind and beside the hero. A single circle is the one on the hero. Ids are left to the caller. A cutter
 * that would leave no safe spot is left out; a circle over one of the Pickups is pushed off it.
 */
JAMGAME_API TArray<FJamHazard> Pattern(const FVector2D& BossPos, const FVector2D& HeroPos, int32 Count, const TArray<FJamPickup>& Pickups,
	int32 Tick, FRandomStream& Stream, const FJamBalanceData& Balance);

/**
 * The nearest spot that a fighter at Pos, walking straight at the hero's speed after ReactionSeconds, reaches without
 * being inside any of the Hazards on the step it lands. Unset when there is none.
 */
JAMGAME_API TOptional<FVector2D> SafeSpot(
	const TArray<FJamHazard>& Hazards, const FVector2D& Pos, int32 Tick, float ReactionSeconds, const FJamBalanceData& Balance);
} // namespace JamSlamRules

