/** Room between the edges of two circles; negative when they overlap. */
double GapBetween(const FJamHazard& A, const FJamHazard& B)
{
	return FVector2D::Distance(A.Pos, B.Pos) - A.Radius - B.Radius;
}

/**
 * Pushes Hazard away from each of the Placed circles until the gap is left between their edges, keeps it on the
 * floor and off the cash. False when the wall or the cash leaves it no room.
 */
bool MakeRoom(FJamHazard& Hazard, const TArray<FJamHazard>& Placed, const TArray<FJamPickup>& Pickups, const FVector2D& Fallback,
	const FJamBalanceData& Balance)
{
	// A push off one circle can land on another: a few rounds settle it, or the circle is given up.
	constexpr int32 Rounds = 4;
	const double Room = Balance.ArenaRadius;
	for (int32 Round = 0; Round < Rounds; ++Round)
	{
		for (const FJamHazard& Other : Placed)
		{
			const double Need = Other.Radius + Hazard.Radius + Balance.SlamGap;
			const FVector2D From = Hazard.Pos - Other.Pos;
			if (From.SizeSquared() < Need * Need)
			{
				Hazard.Pos = Other.Pos + (From.IsNearlyZero() ? Fallback : From.GetSafeNormal()) * Need;
			}
		}
		Hazard.Pos = Hazard.Pos.Size() > Room ? Hazard.Pos.GetSafeNormal() * Room : Hazard.Pos;
		KeepOffTheCash(Hazard, Pickups, Fallback, Balance);
	}
	for (const FJamHazard& Other : Placed)
	{
		if (GapBetween(Hazard, Other) < Balance.SlamGap - 0.1)
		{
			return false;
		}
	}
	for (const FJamPickup& Cash : Pickups)
	{
		if (FVector2D::Distance(Hazard.Pos, Cash.Pos) < Hazard.Radius + Balance.HealPickupRadius - 0.1)
		{
			return false;
		}
	}
	return Hazard.Pos.Size() <= Room + 0.1;
}

/**
 * Five circles (T-052): two at the Publisher's flanks, then the one on the hero, then two wide behind the hero on
 * either side of his way back. Each keeps the gap to the ones placed before it or is left out; the one on the hero is
 * placed first and always stays. Returned in landing order, from him outwards.
 */
TArray<FJamHazard> SpreadPattern(const FVector2D& BossPos, const FVector2D& HeroPos, const FVector2D& Away, const float (&Jitters)[3],
	const TArray<FJamPickup>& Pickups, int32 Tick, const FJamBalanceData& Balance)
{
	const double NearDistance = Balance.SlamSideRadius + 0.5 * Balance.SlamGap;
	const double WideDistance = Balance.SlamRadius + Balance.SlamSideRadius + Balance.SlamGap;
	const FVector2D Back = -Away;
	// Landing rank and centre of each circle, the hero's first: the order they claim the floor in.
	const TPair<int32, FVector2D> Wanted[] = {
		{ 2, HeroPos },
		{ 0, BossPos + Away.GetRotated(90.f + Jitters[0]) * NearDistance },
		{ 1, BossPos + Away.GetRotated(-90.f + Jitters[0]) * NearDistance },
		{ 3, HeroPos + Back.GetRotated(Balance.SlamSpreadAngle + Jitters[1]) * WideDistance },
		{ 4, HeroPos + Back.GetRotated(-Balance.SlamSpreadAngle + Jitters[2]) * WideDistance },
	};
	TArray<FJamHazard> Placed;
	TArray<int32> Ranks;
	for (const TPair<int32, FVector2D>& Want : Wanted)
	{
		const bool bOnHero = Want.Key == 2;
		FJamHazard Hazard = Circle(Want.Value, bOnHero ? Balance.SlamRadius : Balance.SlamSideRadius, 0, Tick, Balance);
		if (bOnHero)
		{
			KeepOffTheCash(Hazard, Pickups, Away, Balance);
		}
		else if (!MakeRoom(Hazard, Placed, Pickups, (Want.Value - HeroPos).GetSafeNormal(), Balance))
		{
			continue;
		}
		Placed.Add(Hazard);
		Ranks.Add(Want.Key);
	}
	TArray<FJamHazard> Result;
	for (int32 Rank = 0; Rank < UE_ARRAY_COUNT(Wanted); ++Rank)
	{
		const int32 Index = Ranks.Find(Rank);
		if (Index != INDEX_NONE)
		{
			Result.Add(Circle(Placed[Index].Pos, Placed[Index].Radius, Result.Num(), Tick, Balance));
		}
	}
	return Result;
}

