bool MakeRoom(FJamHazard& Hazard, const TArray<FJamHazard>& Placed, const TArray<FJamPickup>& Pickups, const FVector2D& Fallback,
	const FJamBalanceData& Balance)
{
	// A push off one circle can land on another: a few rounds settle it, or the circle is given up.
	constexpr int32 Rounds = 4;
	const double Room = Balance.ArenaRadius;
	for (int32 Round = 0; Round < Rounds; ++Round)
	{
		for (const FJamHazard& Other : Placed)
		{
			const double Need = Other.Radius + Hazard.Radius + Balance.SlamGap;
			const FVector2D From = Hazard.Pos - Other.Pos;
			if (From.SizeSquared() < Need * Need)
			{
				Hazard.Pos = Other.Pos + (From.IsNearlyZero() ? Fallback : From.GetSafeNormal()) * Need;
			}
		}
		Hazard.Pos = Hazard.Pos.Size() > Room ? Hazard.Pos.GetSafeNormal() * Room : Hazard.Pos;
		KeepOffTheCash(Hazard, Pickups, Fallback, Balance);
	}
	for (const FJamHazard& Other : Placed)
	{
		if (GapBetween(Hazard, Other) < Balance.SlamGap - 0.1)
		{
			return false;
		}
	}
	for (const FJamPickup& Cash : Pickups)
	{
		if (FVector2D::Distance(Hazard.Pos, Cash.Pos) < Hazard.Radius + Balance.HealPickupRadius - 0.1)
		{
			return false;
		}
	}
	return Hazard.Pos.Size() <= Room + 0.1;
}

