/**
 * The place nearest to Dir on a ring of Distance around Anchor where a circle has room: the wanted direction first,
 * then turning further either way, then a wider ring. Unset when the floor has no such place.
 */
TOptional<FVector2D> FindRoom(const FVector2D& Anchor, const FVector2D& Dir, double Distance, double Radius, const TArray<FJamHazard>& Placed,
	const TArray<FJamPickup>& Pickups, const FJamBalanceData& Balance)
{
	constexpr float TurnStep = 15.f;
	constexpr int32 Rings = 4;
	constexpr double RingStep = 100.0;
	for (int32 Ring = 0; Ring < Rings; ++Ring)
	{
		for (float Turn = 0.f; Turn <= 180.f; Turn += TurnStep)
		{
			for (const float Side : { 1.f, -1.f })
			{
				const FVector2D Pos = Anchor + Dir.GetRotated(Side * Turn) * (Distance + Ring * RingStep);
				if (HasRoom(Pos, Radius, Placed, Pickups, Balance))
				{
					return Pos;
				}
			}
		}
	}
	return {};
}

