153		const FVector2D Back = Three[2].Pos - Hero;
154		TestEqual(TEXT("the third cuts the way back at the cutter distance"), Back.Size(), static_cast<double>(B.SlamCutterDistance), 1.0);
155		TestTrue(TEXT("behind the hero, within the jitter"), DegreesBetween(Back, WayBack) <= B.SlamJitter + 0.5);
156	
157		// T-052: five circles spread out: two at his flanks, three wide, with room to stand between any two of them.
158		const TArray<FJamHazard> Five = MakePattern(Boss, Hero, 5, 1, B);
159		if (!TestEqual(TEXT("five circles after the second cut"), Five.Num(), 5))
160		{
161			return false;
162		}
163		const FVector2D ToHero = Hero - Boss;
164		TestTrue(TEXT("the first two on both sides of him"),
165			FVector2D::CrossProduct(ToHero, Five[0].Pos - Boss) * FVector2D::CrossProduct(ToHero, Five[1].Pos - Boss) < 0.0);
166		for (const int32 Near : { 0, 1 })
